@app.get('/api/signatures/{sig_request_id}/document')
def get_signing_contract_document(
    sig_request_id: UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    request_obj = db.query(SignatureWorkflow).filter(
        SignatureWorkflow.id == sig_request_id,
        or_(SignatureWorkflow.sender_id == current_user.id, SignatureWorkflow.signer_email == current_user.email)
    ).first()
    if not request_obj or not os.path.exists(request_obj.unsigned_document_path):
        raise HTTPException(status_code=404, detail="Document for signature not found")

    return FileResponse(
        path=request_obj.unsigned_document_path,
        filename=request_obj.document_title,
        media_type="application/pdf"
    )
